/**
 * Logical operators (AND, OR, NOT)
 * Handles rule composition and boolean logic
 */
export class LogicalOperators extends BaseOperator {
    /**
     * Register logical operators with the engine
     */
    register(engine: any): void;
    /**
     * Create AND operator
     */
    createAndOperator(): (args: any, context: any, evaluateExpr: any, depth: any) => boolean;
    /**
     * Create OR operator
     */
    createOrOperator(): (args: any, context: any, evaluateExpr: any, depth: any) => boolean;
    /**
     * Create NOT operator
     */
    createNotOperator(): (args: any, context: any, evaluateExpr: any, depth: any) => boolean;
}
import { BaseOperator } from './base/BaseOperator.js';
